import { splitFrames } from './split-frames.mjs';
export function createFramer({delimiter='\r\n',maxBuffer=1024}={}) {
  let pending='';
  return {
    push(chunk){pending+=chunk;const out=splitFrames(pending,delimiter);pending=out.rest;return out.frames;},
    finish(){return pending?[pending]:[];},
  };
}

