import { isExpired } from './expiry.mjs';
export function createCache({ capacity = 3, ttl = 1000, now = Date.now } = {}) {
  const entries = new Map();
  const prune = () => {
    for (const [key, entry] of entries) {
      if (isExpired(entry, now())) entries.delete(key);
    }
  };
  return {
    set(key, value) {
      prune();
      if (entries.size >= capacity) entries.delete(entries.keys().next().value);
      entries.set(key, { value, deadline: now() + ttl });
    },
    get(key) {
      prune();
      const entry = entries.get(key);
      if (!entry?.value) return undefined;
      return entry.value;
    },
    has(key) { prune(); return entries.has(key); },
    size() { return entries.size; },
  };
}

